const fight=createFight({team:()=>state.team,level:id=>lv(id).level,name:id=>pool[id-1].name,types:id=>types[id],wildLevel:minLevel,info:id=>{const l=lv(id);return{level:l.level,pct:l.capped?100:Math.round(l.xp/l.need*100),text:l.capped?(l.evolvesAt?'Niveau max du stade':'Niveau max'):`XP ${l.xp} / ${l.need}`};},sprite,backSprite:id=>`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/back/${id}.png`,reduced:()=>state.reducedMotion||prefersReduced(),
 addXp(id,n){const before=lv(id).level;state.xp[id]=(state.xp[id]||0)+n;const after=lv(id).level;save();return{before,after};},
 onEnd(){render();},onContinue(){resetEncounter();},onFlee(){resetEncounter();}});
