let backdropKey='';
function renderZones(){const zone=zones.find(z=>z.id===state.zone);$('#location-chip').textContent=zone.name;$('#active-bonus').textContent=zone.note;$('#map-place').textContent=zone.name;$('#map-mount').innerHTML=mapMarkup(state.zone,busy);const key=state.zone+':'+state.reducedMotion;if(backdropKey!==key){backdropKey=key;$('#scenery').style.backgroundImage=`url("${backgroundFor(state.zone)}")`;$('#scenery').setAttribute('aria-label','Décor : '+zone.name);wanderers.setZone(state.zone);}wanderers.setReduced(state.reducedMotion||prefersReduced());}
